def predict_smiles(caption):
    if "thiophene" in caption:
        return "S1=CC=CS1"
    elif "naphthalene" in caption:
        return "CNC1=CC2=C(C=C1)C=C(C=C2)NC"
    elif "diphenylacetylene" in caption:
        return "C1=CC(=CC=C1C#CC2=CC=C(C=C2)N)N"
    elif "five aromatic heterocycle" in caption:
        return "C1=COC=C1"
    else:
        return None

print(predict_smiles("This molecule contains two thiophene groups that are attached to serve as anchor groups."))
